/// #572: claude のメッセージキューから未送信の指示を取り出すキー（`Up`）。
/// claude 自身が `Press up to edit queued messages` と案内している操作
const QUEUE_RECALL_BYTES: &[u8] = b"\x1b[A";

/// #572: 「idle なのにキューが残っている」を何 tick（2 秒周期）連続で観測したら救出するか。
/// claude 自身のドレインは実測でターン終了から 1 秒以内なので、3 tick = 6 秒あれば
/// 正常な自動送信と競合しない
const QUEUE_STRANDED_TICKS: u8 = 3;

/// #572: 1 ペインあたりの救出試行の上限（滞留が解けないときに叩き続けない）
const QUEUE_RECOVERY_MAX: u8 = 5;

/// #749: master ペインごとの自動ハンドオフ通知の追跡状態。
/// 判定そのものは `tako_core::handoff::nudge_decision` が持つ（ここは観測値の保管だけ）
#[derive(Debug)]
struct HandoffNudgeTracker {
    /// このペインを最初に観測した時刻（起動直後の猶予 NUDGE_GRACE の基準）
    first_seen: std::time::Instant,
    /// 最後にナッジを送った時刻
    last_sent: Option<std::time::Instant>,
    /// 送った回数
    sent: u32,
}

impl HandoffNudgeTracker {
    fn new(now: std::time::Instant) -> Self {
        Self {
            first_seen: now,
            last_sent: None,
            sent: 0,
        }
    }
}

/// #572: キュー滞留の救出状態（ペインごと）
#[derive(Debug, Default)]
struct QueuedRecovery {
    /// 「キュー滞留 + 画面が前 tick から変化なし」を連続観測した回数
    idle_ticks: u8,
    /// 直前 tick の画面（生成中かどうかを文言でなく変化の有無で見る）
    last_screen: Option<Vec<String>>,
    /// 救出（Enter 単独送達フロー）を積んだ回数
    attempts: u8,
    /// 上限到達の警告を出したか（毎 tick 出さないため）
    gave_up: bool,
}

/// #572: 1 tick 観測した結果、何をすべきか
#[derive(Debug, PartialEq, Eq)]
enum QueuedRecoveryAction {
    /// まだ様子を見る（生成中 / 観測回数が足りない / 打ち切り済み）
    Wait,
    /// 救出する（Enter 単独送達フローを積む）
    Deliver,
    /// 上限に達したので警告して打ち切る（この tick だけ警告を出す）
    GiveUp,
}

impl QueuedRecovery {
    /// 「キュー滞留を検知したペイン」の 1 tick 分の観測を反映して次の行動を決める。
    ///
    /// 生成中に割り込むと、取り出したメッセージが再びキューへ戻るだけで何も進まない。
    /// 生成中かどうかは `is_busy` の文言ではなく **画面が前 tick から変化していない
    /// こと** で見る（実測で 120 行のリスト生成中に `is_busy` が false を返した）
    fn observe(&mut self, lines: Vec<String>) -> QueuedRecoveryAction {
        let settled = self
            .last_screen
            .as_ref()
            .is_some_and(|before| tako_control::claude_tui::screen_settled(before, &lines));
        self.last_screen = Some(lines);
        if !settled {
            self.idle_ticks = 0;
            return QueuedRecoveryAction::Wait;
        }
        self.idle_ticks = self.idle_ticks.saturating_add(1);
        if self.idle_ticks < QUEUE_STRANDED_TICKS {
            return QueuedRecoveryAction::Wait;
        }
        if self.attempts >= QUEUE_RECOVERY_MAX {
            if self.gave_up {
                return QueuedRecoveryAction::Wait;
            }
            self.gave_up = true;
            return QueuedRecoveryAction::GiveUp;
        }
        self.attempts = self.attempts.saturating_add(1);
        self.idle_ticks = 0;
        QueuedRecoveryAction::Deliver
    }
}

/// claude TUI へのプロンプト送信フローの状態（Issue #32 送達確認ループ）
#[derive(Debug)]
enum PromptFlowState {
    /// alt_screen 遷移待ち（claude TUI の起動待ち。spawn / await_prompt 経路のみ）
    WaitAltScreen,
    /// 送信可能待ち: 信頼ダイアログが出ていれば承諾し、入力欄（プロンプト記号）表示で貼り付ける。
    /// 信頼ダイアログも選択カーソルに同じプロンプト記号を含むため、ダイアログ判定を先に行う
    WaitPromptReady,
    /// 貼り付け済み、入力欄への反映待ち。反映確認後に送信の Enter を
    /// 貼り付けと分離した単独キーとして送る（次 tick = 500ms 以上の遅延）
    WaitTextInInput,
    /// Enter 送信済み。入力欄が空へ戻った（= 送信された）ことを検証し、
    /// 残っていれば Enter を単独再送する
    VerifySubmitted,
    /// 完了
    Done,
}

/// 新規ペインの素のシェルへ起動コマンドを送り届けるフロー（Issue #640）。
/// 判断は純粋な `tako_core::shell_send::ShellSendFlow` が持ち、ここは
/// 「どのペインか」と「いつ諦めるか」だけを持つ
#[derive(Debug)]
struct ShellCommandFlow {
    pane: PaneId,
    flow: tako_core::shell_send::ShellSendFlow,
    created_at: std::time::Instant,
}

/// 起動コマンド送達フローの打ち切り時間。
/// シェルの起動待ち（最大 30 秒）+ 書き直し 10 回（約 35 秒）+ Enter 再送（約 12 秒）を
/// 足しても収まる長さ。ここを過ぎたら諦めて痕跡だけ残す
const COMMAND_FLOW_TIMEOUT: Duration = Duration::from_secs(120);

/// claude TUI へのプロンプト送達ステートマシン（500ms tick で `drive_prompt_flows` が駆動）
#[derive(Debug)]
struct PromptFlow {
    pane: PaneId,
    prompt: String,
    state: PromptFlowState,
    created_at: std::time::Instant,
    /// 現在のステートに遷移した時刻（ステート内タイムアウト用）
    state_entered_at: std::time::Instant,
    /// 信頼ダイアログを承諾した回数（無限承諾ループ防止。上限 3）
    trust_accepts: u8,
    /// 入力欄残留に対する Enter 単独再送の残り回数
    enter_retries_left: u8,
    /// 貼り付けが入力欄に反映されなかった場合の再貼り付け残り回数（#390）。
    /// claude TUI の起動完了前に貼り付けると raw mode 切替の狭間で吸われ、
    /// 入力欄が空のまま「送信成功」と誤判定される競合への対策
    paste_retries_left: u8,
    /// true = claude TUI の起動（alt_screen + プロンプト記号）を待つ（spawn / await_prompt）。
    /// false = 現画面へ即貼り付けの汎用送信（TUI でなければ 2 秒待って貼る）
    wait_tui: bool,
    /// Enter 単独送達モード（Issue #95）: 貼り付けせず Enter を送り、入力欄が
    /// 空へ戻るまで単独再送する（入力欄に残留したテキストの送信代行）
    enter_only: bool,
    /// enter_only の残留判定基準: Enter 送信時点の入力欄内容。検証時に
    /// 同じ内容が残っていれば未送達とみなし Enter を再送する
    baseline: Option<String>,
    /// 直前 tick の画面（#572。キュー救出の前に「生成中でない」を画面の
    /// 変化の有無で見るために保持する。`is_busy` の文言判定は空振りする）
    prev_screen: Option<Vec<String>>,
    /// キュー滞留からの取り出し（`Up`）を送った回数（#572。上限 2）。
    /// claude は busy 中に打たれた指示を内部キューへ入れる。ターン終了時に自動で
    /// 送信されるが、残ったままになると入力欄自体は空なので Enter は no-op になり、
    /// Enter 単独送達（#95）が永久に空振りする
    queue_recalls: u8,
    /// 貼り付けが入力欄へ反映されたことを確認できたか（Issue #530）。
    /// 「入力欄が空」は送信の証拠にならない（貼り付けが届いていなければ最初から空）ため、
    /// 送達の確証はこのフラグと残留消失の**両方**が揃ったときだけとする
    paste_reflected: bool,
    /// 未達で打ち切ったときの理由コード（規約により画面内容・送信テキストは含めない）
    unverified_reason: Option<&'static str>,
    /// worker レジストリへ初回プロンプトの送達結果を記録するフローか。
    /// 通常の後続 send は同じ送達確認ループを使うが、spawn の状態は変更しない（#778）
    delivery_flow: tako_control::orchestrator::registry::PromptDeliveryFlow,
    /// peer 送達（#790。claude の Cross-Session Messaging）の非同期試行。
    /// socket 接続と transcript による受信確認は待ちを含むので background で走らせ、
    /// 結果をこのスロットへ書く。None = まだ試していない
    peer_attempt: Option<std::sync::Arc<std::sync::Mutex<Option<PeerAttemptResult>>>>,
}

/// 送達フローから見た peer 送達の 1 tick ぶんの進み（#790）
enum PeerStep {
    /// background の試行中（次 tick で結果を見る）
    Pending,
    /// peer で送り切った
    Sent {
        /// transcript で受信を確認できたか
        received: bool,
    },
    /// peer は使えない → 従来のキー操作経路へ（理由は診断ログへ残す）
    UseKeys { reason: &'static str },
    /// `TAKO_PEER_MESSAGING=only` で peer が使えなかった（検証用。キー経路へ落ちない）
    Refused { note: String },
}

/// background で走らせた peer 送達の結果（#790）
#[derive(Debug, Clone)]
enum PeerAttemptResult {
    /// peer で送り切った（**キー操作経路へ落ちてはならない** = 二重投函の防止）
    Sent {
        /// transcript による受信確認
        received: bool,
    },
    /// peer は使えなかった。キー操作経路へ落ちてよい
    Fallback {
        /// 安定した理由コード（診断ログ用）
        reason: &'static str,
        /// 待てば解消しうる理由か（claude が起動途中で受信箱をまだ開いていない等）
        transient: bool,
    },
    /// `TAKO_PEER_MESSAGING=only` で peer が使えなかった（検証用）
    Refused { note: String },
}

/// 一時的な不成立（起動途中で受信箱がまだ無い）を待つ猶予。
/// claude の受信箱 bind は入力欄表示とほぼ同時（実測 1.1 秒）だが、負荷が高いと遅れる。
/// 猶予を過ぎたら従来経路へ落ちる（待ち続けて送達が遅れる方が悪い）
const PEER_GRACE: std::time::Duration = std::time::Duration::from_secs(6);

impl PromptFlow {
    fn new(
        pane: PaneId,
        prompt: String,
        wait_tui: bool,
        delivery_flow: tako_control::orchestrator::registry::PromptDeliveryFlow,
    ) -> Self {
        let now = std::time::Instant::now();
        Self {
            pane,
            // 送信の Enter は分離して送るため末尾改行は落とす
            prompt: prompt.trim_end_matches(['\n', '\r']).to_string(),
            state: if wait_tui {
                PromptFlowState::WaitAltScreen
            } else {
                PromptFlowState::WaitPromptReady
            },
            created_at: now,
            state_entered_at: now,
            trust_accepts: 0,
            enter_retries_left: 4,
            paste_retries_left: 2,
            wait_tui,
            enter_only: false,
            baseline: None,
            prev_screen: None,
            queue_recalls: 0,
            paste_reflected: false,
            unverified_reason: None,
            delivery_flow,
            peer_attempt: None,
        }
    }

    /// Enter 単独送達フロー（Issue #95）: dispatch の Enter 単独送信
    /// （text が空 / 改行のみ）用。信頼ダイアログ処理 → Enter → 空検証 + 再送
    fn new_enter_only(pane: PaneId) -> Self {
        let mut flow = Self::new(
            pane,
            String::new(),
            false,
            tako_control::orchestrator::registry::PromptDeliveryFlow::FollowUpSend,
        );
        flow.enter_only = true;
        flow
    }

    /// 人間の Enter の送達検証フロー（Issue #95）: Enter は handle_key で書き込み済み
    /// のため検証（VerifySubmitted）から開始する。`baseline` は Enter 書き込み直前の
    /// 入力欄内容（同じ内容が残っていれば未送達 = Enter を単独再送）
    fn new_enter_verify(pane: PaneId, baseline: String) -> Self {
        let mut flow = Self::new(
            pane,
            String::new(),
            false,
            tako_control::orchestrator::registry::PromptDeliveryFlow::FollowUpSend,
        );
        flow.enter_only = true;
        flow.baseline = Some(baseline);
        flow.state = PromptFlowState::VerifySubmitted;
        flow
    }
}

fn rgba(c: tako_core::Rgb) -> Rgba {
    Rgba {
        r: c.r as f32 / 255.0,
        g: c.g as f32 / 255.0,
        b: c.b as f32 / 255.0,
        a: 1.0,
    }
}

fn hsla(c: tako_core::Rgb) -> Hsla {
    rgba(c).into()
}

/// 半透明色（スクロールバー等のオーバーレイ用）
pub(crate) fn rgba_alpha(c: tako_core::Rgb, a: f32) -> Rgba {
    Rgba { a, ..rgba(c) }
}

/// 経過秒の相対表記（tmuxview の作成日時表示用。文言は ui_text::common）
fn format_age(seconds: i64) -> String {
    crate::ui_text::common::format_age(seconds)
}

fn hsla_alpha(c: tako_core::Rgb, a: f32) -> Hsla {
    rgba_alpha(c, a).into()
}

/// 自動リネーム（FR-2.12.4）の起動時の有効判定。
/// セルフテストでは検知ループを止める（トグル・適用経路だけを機械検証する）。
/// `TAKO_AUTO_RENAME=0|false|off` は設定ファイルより優先して無効化する
fn initial_auto_rename() -> bool {
    if std::env::var_os("TAKO_SELF_TEST").is_some() {
        return false;
    }
    if matches!(
        std::env::var("TAKO_AUTO_RENAME").ok().as_deref(),
        Some("0" | "false" | "off")
    ) {
        return false;
    }
    tako_control::settings::load().auto_rename
}

/// listen ポート検知（FR-2.4.4）の起動時の有効判定。
/// セルフテストでは検知経路そのものを機械検証するため常に有効で始める
fn initial_port_detect() -> bool {
    if std::env::var_os("TAKO_SELF_TEST").is_some() {
        return true;
    }
    if matches!(
        std::env::var("TAKO_PORT_DETECT").ok().as_deref(),
        Some("0" | "false" | "off")
    ) {
        return false;
    }
    tako_control::settings::load().port_detect
}

