/// リモート操作の通知（#919）。
///
/// 汎用のトーストが無いので、**ユーザーが見ている場所**（ファイルツリーの上）へ出す。
/// 成功は数秒で消え、失敗は次の操作まで残る（理由を読む時間を奪わない）
struct RemoteNotice {
    text: String,
    is_error: bool,
    at: std::time::Instant,
}

impl RemoteNotice {
    /// 成功通知が消えるまで
    const SUCCESS_TTL: Duration = Duration::from_secs(8);

    fn expired(&self) -> bool {
        !self.is_error && self.at.elapsed() > Self::SUCCESS_TTL
    }
}

