#[cfg(test)]
mod git_ancestor_tests {
    use super::has_git_ancestor;

    #[test]
    fn gitリポジトリ内のディレクトリで_true() {
        let dir = std::env::current_dir().unwrap();
        assert!(has_git_ancestor(&dir));
    }

    #[test]
    fn gitリポジトリ内のサブディレクトリで_true() {
        let dir = std::env::current_dir().unwrap().join("crates");
        if dir.is_dir() {
            assert!(has_git_ancestor(&dir));
        }
    }

    #[test]
    fn ルートディレクトリで_false() {
        assert!(!has_git_ancestor(std::path::Path::new("/")));
    }

    #[test]
    fn 一時ディレクトリで_false() {
        let dir = std::env::temp_dir().join("tako-test-no-git");
        let _ = std::fs::create_dir_all(&dir);
        assert!(!has_git_ancestor(&dir));
        let _ = std::fs::remove_dir(&dir);
    }
}

#[cfg(test)]
mod menu_position_tests {
    use super::compute_menu_position;

    #[test]
    fn メニューが収まる場合はそのまま() {
        let (x, y) = compute_menu_position(100.0, 200.0, 180.0, 250.0, 1200.0, 800.0);
        assert_eq!(x, 100.0);
        assert_eq!(y, 200.0);
    }

    #[test]
    fn 右端を超えたら左へフリップ() {
        let (x, y) = compute_menu_position(1100.0, 200.0, 180.0, 250.0, 1200.0, 800.0);
        assert_eq!(x, 1100.0 - 180.0);
        assert_eq!(y, 200.0);
    }

    #[test]
    fn 下端を超えたら上へフリップ() {
        let (x, y) = compute_menu_position(100.0, 700.0, 180.0, 250.0, 1200.0, 800.0);
        assert_eq!(x, 100.0);
        assert_eq!(y, 700.0 - 250.0);
    }

    #[test]
    fn 両方超えたら両方フリップ() {
        let (x, y) = compute_menu_position(1100.0, 700.0, 180.0, 250.0, 1200.0, 800.0);
        assert_eq!(x, 1100.0 - 180.0);
        assert_eq!(y, 700.0 - 250.0);
    }

    #[test]
    fn フリップ後も負にならない() {
        let (x, y) = compute_menu_position(50.0, 30.0, 180.0, 250.0, 100.0, 100.0);
        assert_eq!(x, 0.0);
        assert_eq!(y, 0.0);
    }
}

#[cfg(test)]
mod drag_scroll_tests {
    use super::*;

    #[test]
    fn 最小速度係数では最小速度になる() {
        let delta = drag_scroll_delta(0.0);
        let expected = DRAG_SCROLL_MIN_SPEED * (DRAG_SCROLL_INTERVAL_MS as f32 / 1000.0);
        assert!((delta - expected).abs() < 0.001);
    }

    #[test]
    fn 最大速度係数では最大速度になる() {
        let delta = drag_scroll_delta(1.0);
        let expected = DRAG_SCROLL_MAX_SPEED * (DRAG_SCROLL_INTERVAL_MS as f32 / 1000.0);
        assert!((delta - expected).abs() < 0.001);
    }

    #[test]
    fn 中間係数は最小と最大の間に収まる() {
        let min = drag_scroll_delta(0.0);
        let max = drag_scroll_delta(1.0);
        let mid = drag_scroll_delta(0.5);
        assert!(mid > min);
        assert!(mid < max);
    }

    #[test]
    fn 速度は単調増加する() {
        let mut prev = drag_scroll_delta(0.0);
        for i in 1..=10 {
            let factor = i as f32 / 10.0;
            let delta = drag_scroll_delta(factor);
            assert!(delta > prev, "factor={factor}: {delta} <= {prev}");
            prev = delta;
        }
    }

    // --- PDF プレビュー用（#309） ---

    #[test]
    fn pdf_最小速度係数では最小ピクセル速度になる() {
        let delta = drag_scroll_delta_px(0.0);
        let expected = DRAG_SCROLL_MIN_PX_PER_SEC * (DRAG_SCROLL_INTERVAL_MS as f32 / 1000.0);
        assert!((delta - expected).abs() < 0.01);
    }

    #[test]
    fn pdf_最大速度係数では最大ピクセル速度になる() {
        let delta = drag_scroll_delta_px(1.0);
        let expected = DRAG_SCROLL_MAX_PX_PER_SEC * (DRAG_SCROLL_INTERVAL_MS as f32 / 1000.0);
        assert!((delta - expected).abs() < 0.01);
    }

    #[test]
    fn pdf_速度は単調増加する() {
        let mut prev = drag_scroll_delta_px(0.0);
        for i in 1..=10 {
            let factor = i as f32 / 10.0;
            let delta = drag_scroll_delta_px(factor);
            assert!(delta > prev, "factor={factor}: {delta} <= {prev}");
            prev = delta;
        }
    }
}

/// アプリケーションメニュー（#485）の構造検査。
/// 「無反応のダミー項目を置かない」を機械的に固定する
#[cfg(test)]
mod app_menu_tests {
    use super::*;
    use gpui::{Menu, MenuItem};

    /// メニュー木を辿って (表示名, アクション名) を集める
    fn collect_actions(items: &[MenuItem], out: &mut Vec<(String, String)>) {
        for item in items {
            match item {
                MenuItem::Action { name, action, .. } => {
                    out.push((name.to_string(), action.name().to_string()));
                }
                MenuItem::Submenu(sub) => collect_actions(&sub.items, out),
                MenuItem::Separator | MenuItem::SystemMenu(_) => {}
            }
        }
    }

    fn all_actions(menus: &[Menu]) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for menu in menus {
            collect_actions(&menu.items, &mut out);
        }
        out
    }

    #[test]
    fn 全項目が実在のアクションに配線されている() {
        // ハンドラ登録（グローバル cx.on_action / ルート div の on_action）は
        // すべて main.rs にある。ソースを走査して「メニューにあるのに
        // ハンドラが無い」＝ 押しても無反応のダミーを検出する
        let source = include_str!("main.rs");
        let menus = app_menus();
        let actions = all_actions(&menus);
        assert!(actions.len() >= 30, "項目数が少なすぎる: {}", actions.len());
        for (label, action) in &actions {
            assert!(
                action != "gpui::NoAction",
                "ダミー項目（NoAction）が残っている: {label}"
            );
            let short = action.strip_prefix("tako::").unwrap_or_else(|| {
                panic!("tako 名前空間のアクションではない: {label} -> {action}")
            });
            assert!(
                source.contains(&format!("&{short},")),
                "{label} のアクション {action} に on_action ハンドラが無い"
            );
        }
    }

    /// macOS のアプリ名メニュー（#485）。Windows はアプリ名メニューを持たない（#657）
    #[cfg(target_os = "macos")]
    #[test]
    fn takoメニューは標準項目を慣習順に並べる() {
        let menus = app_menus();
        let app_menu = &menus[0];
        assert_eq!(app_menu.name.as_ref(), "tako");
        let actions: Vec<String> = {
            let mut v = Vec::new();
            collect_actions(&app_menu.items, &mut v);
            v.into_iter().map(|(_, a)| a).collect()
        };
        assert_eq!(
            actions,
            vec![
                "tako::AboutTako",
                "tako::CheckForUpdates",
                "tako::OpenSettings",
                "tako::HideApp",
                "tako::HideOthers",
                "tako::ShowAllApps",
                "tako::Quit",
            ]
        );
        // Services は OS 管理のサブメニュー（アクションを持たない）
        assert!(
            app_menu
                .items
                .iter()
                .any(|i| matches!(i, MenuItem::SystemMenu(_))),
            "Services メニューが無い"
        );
    }

    /// macOS: OS のグローバルメニューバーに載るので Apple の作法（アプリ名メニュー先頭）
    #[cfg(target_os = "macos")]
    #[test]
    fn メニュー構成は慣習どおりの並び() {
        let menus = app_menus();
        let names: Vec<&str> = menus.iter().map(|m| m.name.as_ref()).collect();
        assert_eq!(names.len(), 6, "tako / File / Edit / View / Window / Help");
        assert_eq!(names[0], "tako");
    }

    /// Windows: 自前描画のメニューバー行（#657）なので Explorer / VSCode の作法。
    /// **アプリ名メニューを持たず**、About はヘルプ、設定・終了はファイル末尾
    #[cfg(not(target_os = "macos"))]
    #[test]
    fn windowsのメニュー構成はexplorer慣習の並び() {
        let menus = app_menus();
        let names: Vec<&str> = menus.iter().map(|m| m.name.as_ref()).collect();
        assert_eq!(
            names.len(),
            5,
            "ファイル / 編集 / 表示 / ウインドウ / ヘルプ"
        );
        assert_ne!(names[0], "tako", "アプリ名メニューは Windows 慣習に無い");

        let mut file_items = Vec::new();
        collect_actions(&menus[0].items, &mut file_items);
        let file_actions: Vec<&str> = file_items.iter().map(|(_, a)| a.as_str()).collect();
        assert_eq!(
            file_actions.last(),
            Some(&"tako::Quit"),
            "終了はファイルメニューの末尾"
        );
        assert!(
            file_actions.contains(&"tako::OpenSettings"),
            "設定はファイルメニューへ移す"
        );

        let mut help_items = Vec::new();
        collect_actions(&menus[4].items, &mut help_items);
        let help_actions: Vec<&str> = help_items.iter().map(|(_, a)| a.as_str()).collect();
        assert_eq!(
            help_actions,
            vec![
                "tako::AboutTako",
                "tako::CheckForUpdates",
                "tako::OpenDocumentation",
                "tako::ReportIssue",
            ],
            "About と更新確認はヘルプへ移す"
        );
    }

    /// **Windows のメニューに macOS 固有の項目を混ぜてはいけない**（#657 の安全装置）。
    ///
    /// `HideOthers` / `ShowAllApps` は `gpui_windows` の `hide_other_apps` /
    /// `unhide_other_apps` が `unimplemented!()` なので、押せる場所に置くと
    /// **panic = アプリごと abort**（器の無いペインは全滅）する。`keybindings.rs` は
    /// 「バインドが無く、Windows にはメニューバーも無いので到達経路が無い」ことを
    /// 安全根拠にしていた。#657 でメニューバーを作った以上、ここで塞ぐ
    #[cfg(not(target_os = "macos"))]
    #[test]
    fn windowsのメニューにmacos固有の項目が無い() {
        let menus = app_menus();
        let actions: Vec<String> = all_actions(&menus).into_iter().map(|(_, a)| a).collect();
        for forbidden in [
            "tako::HideOthers",  // unimplemented!() = abort
            "tako::ShowAllApps", // unimplemented!() = abort
            "tako::HideApp",     // Windows の hide() は no-op（無反応のダミー禁止）
        ] {
            assert!(
                !actions.iter().any(|a| a == forbidden),
                "{forbidden} が Windows のメニューに混ざっている"
            );
        }
        // Services（OS 管理サブメニュー）も macOS 専用
        for menu in &menus {
            assert!(
                !menu
                    .items
                    .iter()
                    .any(|i| matches!(i, MenuItem::SystemMenu(_))),
                "OS サブメニュー（Services）が Windows のメニューに混ざっている"
            );
        }
    }

    #[test]
    fn 設定はショートカットと同じアクションに配線されている() {
        // 設定のキーバインドとメニューの「設定…」が同一アクション = 同じ動作
        let binding = key_bindings()
            .into_iter()
            .find(|b| b.action().name() == "tako::OpenSettings")
            .expect("設定のバインドが無い");
        assert_eq!(binding.keystrokes()[0].inner().key, ",");
        assert!(binding.keystrokes()[0].inner().modifiers.platform);
        // 置き場所は OS で違う（macOS = tako メニュー / Windows = ファイル末尾。#657）が、
        // 「メニューから設定を開ける」ことは共通
        let menus = app_menus();
        let actions: Vec<String> = all_actions(&menus).into_iter().map(|(_, a)| a).collect();
        assert!(
            actions.iter().any(|a| a == "tako::OpenSettings"),
            "メニューに設定項目が無い"
        );
    }

    /// macOS 慣習のショートカット（#485）は **macOS でだけ**張る（#517 / #585）。
    ///
    /// 非 macOS では `cmd-` が platform 修飾 = Win キーへ解決される。Win+Alt+H が
    /// アプリまで届くと `HideOthers` → `gpui_windows::hide_other_apps` が
    /// `unimplemented!()` で **panic ＝ アプリごと abort**（器の無いペインは全滅）
    /// するため、バインドを張らないことで経路ごと塞いでいる。
    /// **「無いこと」も同じ強さで固定する**（張り直すとここで落ちる）
    #[test]
    fn macos慣習のショートカットがバインドされている() {
        let bindings = key_bindings();
        for (action, key, alt) in [
            ("tako::HideApp", "h", false),
            ("tako::HideOthers", "h", true),
            ("tako::MinimizeWindow", "m", false),
        ] {
            let found = bindings.iter().find(|b| b.action().name() == action);
            if !cfg!(target_os = "macos") {
                assert!(
                    found.is_none(),
                    "{action} のバインドが非 macOS に残っている（Win+Alt+H は \
                     unimplemented! で app ごと落ちる）"
                );
                continue;
            }
            let b = found.unwrap_or_else(|| panic!("{action} のバインドが無い"));
            let ks = b.keystrokes()[0].inner();
            assert_eq!(ks.key, key, "{action}");
            assert!(ks.modifiers.platform, "{action} は cmd 修飾");
            assert_eq!(ks.modifiers.alt, alt, "{action} の alt 修飾");
        }
    }
}

/// ペイン内の「流れの中に積まれる要素」の会計（#781）。
///
/// テキスト領域の矩形は PTY の行数・マウス座標変換（ドラッグ選択）・IME 位置の
/// **共通の正**なので、会計漏れは 3 つ同時のずれになる。実際に stale claude
/// バナー（#498）の 28px が漏れており、claude が自己更新した瞬間から
/// 全 master / worker ペインで選択と IME が約 1.6 行ぶんずれていた
#[cfg(test)]
mod pane_text_area_tests {
    use super::*;

    /// 1 ペインだけのタブ（単位矩形が全面）でのテキスト領域
    fn area(stacked_top: f32, band: f32) -> Bounds<Pixels> {
        let content = Bounds::new(point(px(360.0), px(44.0)), size(px(1000.0), px(800.0)));
        pane_text_area_rect(content, Rect::UNIT, stacked_top, band, 2.0)
    }

    #[test]
    fn バナーぶんだけ下へずれて同じだけ縮む() {
        let without = area(PANE_TITLE_BAR, 0.0);
        let with = area(PANE_TITLE_BAR + STALE_BANNER_HEIGHT, 0.0);
        assert_eq!(
            f32::from(with.origin.y) - f32::from(without.origin.y),
            STALE_BANNER_HEIGHT,
            "バナーはテキストの開始位置を押し下げる"
        );
        assert_eq!(
            f32::from(without.size.height) - f32::from(with.size.height),
            STALE_BANNER_HEIGHT,
            "押し下げたぶんだけ高さも減る（下端がペインの外へ出ない）"
        );
        // 横は変わらない（バナーは全幅なので x 方向の会計は不要）
        assert_eq!(with.origin.x, without.origin.x);
        assert_eq!(with.size.width, without.size.width);
    }

    #[test]
    fn 上の積み上げと下のカード帯は独立に効く() {
        let base = area(PANE_TITLE_BAR, 0.0);
        let banded = area(PANE_TITLE_BAR, 40.0);
        let both = area(PANE_TITLE_BAR + STALE_BANNER_HEIGHT, 40.0);
        assert_eq!(banded.origin.y, base.origin.y, "帯は下なので開始位置は不変");
        assert_eq!(
            f32::from(base.size.height) - f32::from(banded.size.height),
            40.0
        );
        assert_eq!(
            f32::from(base.size.height) - f32::from(both.size.height),
            40.0 + STALE_BANNER_HEIGHT,
            "上下の会計は足し合わせで効く"
        );
    }

    #[test]
    fn 枠と余白の内側から始まる() {
        let a = area(PANE_TITLE_BAR, 0.0);
        // content.origin=(360,44) + 枠 1 + 余白 10、縦はさらにタイトルバー 32
        assert_eq!(f32::from(a.origin.x), 360.0 + PANE_BORDER + PANE_PADDING);
        assert_eq!(
            f32::from(a.origin.y),
            44.0 + PANE_BORDER + PANE_PADDING + PANE_TITLE_BAR
        );
    }

    #[test]
    fn 極端に低いペインでは高さを0へ丸めない() {
        // 0 クランプすると下端が実コンテナの外へ飛び出す（#684 の検査で捕まえた挙動）
        let content = Bounds::new(point(px(0.0), px(0.0)), size(px(400.0), px(20.0)));
        let a = pane_text_area_rect(content, Rect::UNIT, PANE_TITLE_BAR, 0.0, 2.0);
        assert!(f32::from(a.size.height) < 0.0, "負のままにする");
    }

    #[test]
    fn 実描画コンテナからテキスト領域を戻せる() {
        // プローブが採取するのは行スタックの親（四辺 PANE_PADDING の内側が本文）
        let container = Bounds::new(point(px(11.0), px(77.0)), size(px(500.0), px(300.0)));
        let a = text_area_from_container(container);
        assert_eq!(f32::from(a.origin.x), 11.0 + PANE_PADDING);
        assert_eq!(f32::from(a.origin.y), 77.0 + PANE_PADDING);
        assert_eq!(f32::from(a.size.width), 500.0 - PANE_PADDING * 2.0);
        assert_eq!(f32::from(a.size.height), 300.0 - PANE_PADDING * 2.0);
    }

    /// ペイン内に「流れの中」の要素を増やしたら、必ず会計を通ることを構造で担保する。
    ///
    /// 描画側の高さ指定と会計側の定数がずれると座標がずれるので、
    /// バナーの高さ指定が定数経由であること・会計が `render()` の矩形計算で
    /// 呼ばれていることを固定する
    #[test]
    fn バナーの高さ指定と会計が同じ定数を共有している() {
        let source = include_str!("main.rs");
        let flat = source.split_whitespace().collect::<Vec<_>>().join(" ");
        // 描画側: バナー要素の高さ指定が定数経由（生の px 値だと会計側とずれる）
        let banner_element = flat
            .split(&format!("(\"{}\", pane_id.as_u64())", "stale-banner"))
            .nth(1)
            .map(|rest| rest.split(".flex_row()").next().unwrap_or(""))
            .expect("stale バナーの要素が見つからない");
        let shared = format!(".h(px({}))", "STALE_BANNER_HEIGHT");
        assert!(
            banner_element.contains(&shared),
            "バナーの高さが定数経由でない（会計側とずれる）: {banner_element}"
        );
        assert_eq!(
            flat.matches(&shared).count(),
            1,
            "バナーの高さ指定が複数ある（どれが正か分からなくなる）"
        );
        // 会計側: 矩形計算がバナーを足している
        let accounted = format!("PANE_TITLE_BAR + self.{}", "stale_banner_height");
        assert!(
            flat.contains(&accounted),
            "テキスト領域の矩形計算がバナーを会計していない"
        );
        // 矩形を作る式は 1 か所だけ（#684 と同じ方針: 手計算を増やさない）
        let formula = format!("fn {}(", "pane_text_area_rect");
        assert_eq!(flat.matches(&formula).count(), 1);
    }

    /// ターミナルペインの**直接の子**の棚卸し（#781 の再発防止）。
    ///
    /// 流れの中に子を 1 つ足すだけでテキスト領域が下へずれ、ドラッグ選択・IME 位置・
    /// PTY 行数が同時に狂う。`absolute` を付け忘れた子は静かに高さを食うので、
    /// 直接の子の**数**を固定して「増えたら会計を見直す」を強制する
    #[test]
    fn ターミナルペインの直接の子は想定どおり() {
        let source = include_str!("main.rs");
        // ターミナル表示のペインは `render_pane` の最後の分岐なので、
        // ペイン root の直前にある一意な行を起点にする
        // （`.id(("pane", …))` はプレビュー / スターター側にもあるため使えない）
        let pane = source
            .split("let has_link_hover = self")
            .nth(1)
            .expect("ターミナルペインの起点が見つからない");
        // 関数の終わり（4 スペースの閉じ括弧）まで
        let pane = pane.split("\n    }\n").next().expect("ペイン要素の終端");
        assert!(
            pane.contains(&format!(".id((\"{}\", pane_id.as_u64()))", "pane")),
            "起点の直後にペイン root が無い（走査範囲がずれている）"
        );
        // 直接の子 = 12 スペースのインデントで始まるビルダー呼び出し
        let children: Vec<&str> = pane
            .lines()
            .filter_map(|line| {
                let rest = line.strip_prefix("            .")?;
                if line.starts_with("             ") {
                    return None;
                }
                ["child(", "children(", "when(", "when_some("]
                    .into_iter()
                    .find(|head| rest.starts_with(head))
                    .map(|_| rest)
            })
            .collect();
        // 期待する 9 個:
        //   when(is_failed) / when(focused) = 影と枠の見た目だけ（高さを食わない）
        //   child(ヘッダの場所を空けるスペーサー #803) = PANE_TITLE_BAR
        //   when_some(stale バナー) = STALE_BANNER_HEIGHT
        //   child(ターミナル領域) = flex_1
        //   children(カード帯) = card_band_height
        //   children(スクロールバー) / children(提案チップ) / when(workers メニュー) = absolute
        assert_eq!(
            children.len(),
            9,
            "ペインの直接の子が変わっている: {children:#?}\n\
             流れの中（absolute でない）に足したなら `stacked_top` / `band` の会計を\
             見直すこと（#781）"
        );
        // #803: ヘッダの場所は「空けるだけ」でなければならない（実体はルート側）。
        // ここに実要素が戻ると `AnyView::cached` の入れ子になってキャッシュが
        // 一度も当たらなくなる（見た目は変わらないので気づけない）
        let spacer = format!(
            ".child(div().flex_none().w_full().h(px({})))",
            "PANE_TITLE_BAR"
        );
        assert!(
            pane.split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
                .contains(&spacer),
            "ヘッダの場所がスペーサーになっていない（#803 の持ち上げが戻っている）"
        );
    }

    /// ペインヘッダはルート側の兄弟に居る（#803 の持ち上げが戻っていない）。
    ///
    /// GPUI の `AnyView::cached` は入れ子にできないので、ヘッダをペイン本体の内側から
    /// 呼び直すと「PTY 出力では変わらないのに毎フレーム作り直す」へ静かに戻る
    /// （#801 の実測。効果だけが消えて見た目は変わらないため、目視では気づけない）
    #[test]
    fn ペインヘッダはルート側の兄弟として描かれる() {
        let source = include_str!("main.rs");
        let direct = format!("self.{}(", "render_pane_header");
        assert_eq!(
            source.matches(&direct).count(),
            0,
            "ペイン本体からヘッダを直接呼んでいる（キャッシュ単位が入れ子になる。#803）"
        );
        let view_cache = include_str!("view_cache.rs");
        assert_eq!(
            view_cache
                .matches(&format!("app.{}(pane, cx)", "render_pane_header"))
                .count(),
            1,
            "ヘッダの呼び出し元は `view_cache::PaneHeader` 1 か所だけ（#803）"
        );
        let flat = source.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            flat.contains(&format!(".children({})", "pane_headers")),
            "ルートがヘッダ要素を出していない（#803）"
        );
    }
}

/// ペイン矩形の基準になるコンテナ矩形の扱い（#684）。
///
/// `render()` はレイアウト前に走るので「ビューポートからの引き算」は推定にしかならず、
/// 縦に積まれる要素（ウェルカムバナー / アップデート通知カード / たまり場ドロワー /
/// Web ビュー dock）の高さが抜けると PTY の行数が可視行数を超える。
/// 実描画で採取した矩形を正として使うこと自体を、ここで構造的に固定する
#[cfg(test)]
mod pane_content_geometry_tests {
    use super::*;

    fn rect(x: f32, y: f32, w: f32, h: f32) -> Bounds<Pixels> {
        Bounds::new(point(px(x), px(y)), size(px(w), px(h)))
    }

    #[test]
    fn 一致とサブピクセルの揺れでは再描画を要求しない() {
        let used = rect(0.0, 44.0, 1200.0, 700.0);
        assert!(!pane_content_rect_differs(used, used), "完全一致");
        // 0.5px 以下（2x Retina の 1 物理ピクセル未満）は無視する。
        // ここで拾うと毎フレーム再描画を要求し続けることになる
        assert!(
            !pane_content_rect_differs(used, rect(0.4, 44.3, 1199.7, 700.4)),
            "サブピクセルの揺れ"
        );
    }

    #[test]
    fn 四辺のいずれのずれも検出する() {
        let used = rect(0.0, 44.0, 1200.0, 700.0);
        for (label, measured) in [
            ("サイドバー出現", rect(240.0, 44.0, 960.0, 700.0)),
            ("バナー出現で原点が下がる", rect(0.0, 112.0, 1200.0, 632.0)),
            ("右パネル出現で幅が縮む", rect(0.0, 44.0, 900.0, 700.0)),
            ("ドロワー展開で高さが縮む", rect(0.0, 44.0, 1200.0, 460.0)),
        ] {
            assert!(
                pane_content_rect_differs(used, measured),
                "{label} を検出できない"
            );
        }
    }

    #[test]
    fn ずれた実測は一度だけ再描画を要求し収束したら要求しない() {
        let probe = PaneContentProbe::default();
        let baseline = rect(0.0, 44.0, 1200.0, 732.0);
        let banner = rect(0.0, 153.0, 1200.0, 623.0);
        // 推定値で描いてしまったフレームへ、バナーぶん縮んだ実測が来る
        assert!(probe.record(baseline, banner), "ずれたら再描画を要求する");
        assert_eq!(probe.measured.get(), Some(banner));
        // 同じ実測が続くあいだは再要求しない（収束しない経路の安全弁）
        assert!(
            !probe.record(baseline, banner),
            "同じ実測値で再要求しない（vsync ごとの再描画へ落ちない）"
        );
        // 実測を使って描き直せば収束する
        assert!(!probe.record(banner, banner), "収束したら要求しない");
        // バナーを閉じて元へ戻る = 以前要求した値と同じでも改めて要求できる
        assert!(probe.record(banner, baseline), "閉じた側への戻りも要求する");
    }

    #[test]
    fn 実測がペインと同じコンテナで採取され推定は初回フレームだけに使われる() {
        // 空白を畳んで走査する（rustfmt の改行位置に依存させない）。
        // 探す文字列は組み立てる（この検査自身のソースに一致してしまうのを防ぐ）
        let source = include_str!("main.rs");
        let flat = source.split_whitespace().collect::<Vec<_>>().join(" ");
        // プローブはペインとまったく同じ div の子でなければならない
        // （別のコンテナへ移すと測る箱が変わり #684 が再発する）
        let probe = format!(".child({}) .children(panes)", "content_probe");
        assert!(
            flat.contains(&probe),
            "実測プローブがペインと同じコンテナに無い"
        );
        // ジオメトリの式は 1 か所だけ（推定は measured が無いときのフォールバック）
        let formula = format!("viewport.height - px({}())", "top_chrome_height");
        assert_eq!(
            flat.matches(&formula).count(),
            1,
            "ペイン矩形の高さを手計算する式が増えている"
        );
        let fallback = format!("unwrap_or({})", "estimated");
        assert_eq!(
            flat.matches(&fallback).count(),
            1,
            "推定値がフォールバック以外で使われている"
        );
    }

    #[test]
    fn プローブは描画中にエンティティを触らない() {
        // 描画は root view が貸し出されている最中に走ることがあり
        // （`WindowHandle::update` の中から `Window::draw` を呼ぶ経路）、そこで
        // `Entity::update` を呼ぶと abort する = 全ペイン消失。実際に踏んだので、
        // プローブのクロージャが entity を直接触らないことを構造として固定する
        let source = include_str!("main.rs");
        let flat = source.split_whitespace().collect::<Vec<_>>().join(" ");
        let probe_body = flat
            .split(&format!("let {} = {{", "content_probe"))
            .nth(1)
            .and_then(|rest| rest.split(".size_full() };").next())
            .expect("プローブの定義が見つからない");
        // 採取は Cell への書き込みだけ。entity へ触るのは defer の中（貸し出しが解けた後）
        let deferred = probe_body.split("cx.defer").nth(1).unwrap_or("");
        let outside = probe_body.split("cx.defer").next().unwrap_or("");
        assert!(
            outside.contains(&format!("{}.record(used, bounds)", "slot")),
            "採取が Cell 経由でない"
        );
        assert!(
            !outside.contains("entity.update"),
            "描画中に entity を触っている（abort の原因になる）"
        );
        assert!(
            deferred.contains("entity.update"),
            "再描画要求が defer 経由でない"
        );
    }

    /// ルートの flex 列に積まれる「高さを食う子」の棚卸し（#684 受け入れ条件 3）。
    /// 新しい要素が増えても実測経路が正なので破綻しないが、
    /// **absolute を付け忘れたオーバーレイ**は静かに高さを食うので、
    /// 積まれる要素の一覧が想定どおりであることを固定する
    #[test]
    fn ルートに積まれる高さを食う要素は想定どおり() {
        let source = include_str!("main.rs");
        // 起点はタブバー。#786 でキャッシュビュー化したので `ChromePart::TabBar` が目印
        let render = source
            .split("view_cache::ChromePart::TabBar,")
            .nth(1)
            .expect("ルート render が見つからない");
        let render = render
            .split(".child(ime_registration)")
            .next()
            .expect("ルート render の終端が見つからない");
        let stacked: Vec<&str> = [
            "render_welcome_banner",
            "render_update_card",
            "render_drawer",
            "render_webview_dock",
            // ステータスバーも #786 でキャッシュビュー化した
            "view_cache::ChromePart::StatusBar",
        ]
        .into_iter()
        .filter(|name| render.contains(name))
        .collect();
        assert_eq!(
            stacked.len(),
            5,
            "積まれる要素が変わっている: {stacked:?}（実測経路の検証対象を見直すこと）"
        );
    }
}

/// セッション kill の境界を守る番犬（#770）。
///
/// tmux バックエンドセッションは「実行中プロセスの器」なので、kill してよいのは
/// **ユーザー / AI の明示 close だけ**（#30）。アプリ終了（`on_app_quit`）・PTY 死亡・
/// 復元では絶対に kill しない。この不変条件はレビューでしか守られていなかったため、
/// 新しい kill 経路が生えたらここで落ちるようにする。
#[cfg(test)]
mod session_kill_boundary_tests {
    /// `drop_backend_session`（= 実際に kill を撃つ唯一の入口）を呼んでよい場所。
    /// 追加するときは必ず理由を書く（黙って穴を開けない）
    const ALLOWED_CALLERS: &[(&str, &str)] = &[
        (
            "drop_backend_session_with",
            "明示 close だけを kill に通す出し分け（#30）。PTY 死亡はここで弾かれる",
        ),
        (
            "detach_session",
            "ControlHost = CLI / MCP の明示 close（発生源つき）",
        ),
    ];

    /// 走査対象のソース。この番犬モジュール自身（パターン文字列を含む）は除外する
    fn source(rel: &str) -> String {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(rel);
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("{} を読めない: {e}", path.display()));
        let marker = concat!("mod ", "session_kill_boundary_tests");
        match text.find(marker) {
            Some(i) => text[..i].to_string(),
            None => text,
        }
    }

    /// セッション kill の呼び出しが、許可した関数の中だけにあること。
    /// 判定は「直前に現れた `fn 名前(`」で行う（関数境界の近似で十分な粒度）
    #[test]
    fn セッションkillの呼び出しが明示close経路の外に無い() {
        // drawer.rs（たまり場カードの kill 確認）は GUI の明示操作なので別枠で許可する
        let files = ["src/main.rs", "src/drawer.rs"];
        let mut offenders = Vec::new();
        for rel in files {
            let text = source(rel);
            let mut current_fn = String::from("(ファイル先頭)");
            for (i, line) in text.lines().enumerate() {
                if let Some(rest) = line.trim_start().strip_prefix("fn ") {
                    current_fn = rest.split('(').next().unwrap_or("").to_string();
                }
                // 呼び出し形（レシーバつき）だけを見る。定義・ドキュメント中の言及は無視
                if !line.contains(".drop_backend_session(") {
                    continue;
                }
                let allowed = ALLOWED_CALLERS.iter().any(|(f, _)| *f == current_fn)
                    // たまり場ドロワーの kill 確認（GUI の明示操作）はクロージャの中なので
                    // 関数名で切れない。ファイル単位で許可する
                    || rel == "src/drawer.rs";
                if !allowed {
                    offenders.push(format!("{rel}:{} （{current_fn} の中）", i + 1));
                }
            }
        }
        assert!(
            offenders.is_empty(),
            "セッション kill が明示 close 経路の外から呼ばれている:\n  {}\n\
             → 明示 close なら drop_backend_session_with を通し、\
             アプリ終了・PTY 死亡では kill しないこと（#30 / #770）",
            offenders.join("\n  ")
        );
    }

    /// クローズマーカー `close:gui-tab` が **GUI のタブ × 経路でしか付かない**こと（#770）。
    ///
    /// 事故の切り分けはこのマーカーだけを根拠に「再起動ではなくタブ × だった」と
    /// 断定した。別経路（dispatch・内部後始末・アプリ終了）が同じ発生源を名乗ると
    /// 事後調査が成立しなくなるので、`CloseOrigin::TabButton` の出現場所を固定する。
    #[test]
    fn タブcloseの発生源はgui経路だけが名乗る() {
        // 許可: タブ × のハンドラと、その確認ダイアログの承認、およびセルフテストの後始末
        const ALLOWED_FNS: &[&str] = &[
            "close_tab_with_confirm", // タブバーの × ボタン
            "close_confirm_accepted", // その確認ダイアログの「閉じる」
            "remove_tab",             // 既定の発生源を GUI タブ × とするヘルパ
        ];
        let text = source("src/main.rs");
        let mut current_fn = String::from("(ファイル先頭)");
        let mut offenders = Vec::new();
        for (i, line) in text.lines().enumerate() {
            if let Some(rest) = line.trim_start().strip_prefix("fn ") {
                current_fn = rest.split('(').next().unwrap_or("").to_string();
            }
            // 発生源として**渡している**行だけを見る。`.marker()` は
            // 期待値を引くだけの読み取り（セルフテストの検査など）なので対象外
            if !line.contains("CloseOrigin::TabButton") || line.contains(".marker()") {
                continue;
            }
            if !ALLOWED_FNS.contains(&current_fn.as_str()) {
                offenders.push(format!("src/main.rs:{} （{current_fn} の中）", i + 1));
            }
        }
        assert!(
            offenders.is_empty(),
            "close:gui-tab を GUI のタブ × 以外が名乗っている:\n  {}\n\
             → 発生源が混ざると「再起動で消えた / 明示 close で消えた」の\
             事後切り分けができなくなる（#566 / #770）",
            offenders.join("\n  ")
        );
    }

    /// `on_app_quit` に登録する終了処理がセッションを kill しないこと（#770 の受け入れ条件 2）。
    /// quit のクロージャ本体を切り出して、kill 系の呼び出しが含まれないことを見る
    #[test]
    fn アプリ終了処理はセッションをkillしない() {
        let text = source("src/main.rs");
        let start = text
            .find("cx.on_app_quit(")
            .expect("on_app_quit の登録が見つからない（構造が変わったらこの番犬も見直すこと）");
        let body = &text[start..];
        let end = body
            .find("\n        .detach();")
            .expect("on_app_quit クロージャの終端が見つからない");
        let body = &body[..end];
        for forbidden in [
            "drop_backend_session",
            "kill_session",
            "drop_tmux_view_session",
            "remove_pane",
            "remove_tab",
        ] {
            assert!(
                !body.contains(forbidden),
                "アプリ終了処理に {forbidden} が入っている。\
                 quit は detach（セッションを残す）だけで、kill してはいけない（#30 / #770）"
            );
        }
        // 逆に、終了処理が本来やるべきこと（構成の保存）は残っていること
        assert!(
            body.contains("save_layout()"),
            "アプリ終了処理から save_layout が消えている（再起動で構成を失う）"
        );
    }

    /// ウィンドウ 0 枚で無音終了しないこと（#872 の番犬）。
    ///
    /// 症状は「panic でも FAILED でもなく終了コード 0 で消える」= 調査の手がかりが
    /// ゼロ。手がかりを作っている 2 つの仕掛けがソースから消えたら落ちる:
    ///
    /// 1. GPUI の自動終了を止め、方針を tako が持つ（`QuitMode::Explicit` +
    ///    `platform::window_lifecycle`）
    /// 2. ウィンドウが閉じた瞬間を必ず記録する（`on_window_closed` → `viewport_closed_log`）
    #[test]
    fn ウィンドウ0枚の終了は方針と診断を持つ() {
        let text = source("src/main.rs");
        assert!(
            text.contains("cx.set_quit_mode(gpui::QuitMode::Explicit)"),
            "QuitMode::Explicit の指定が消えている。GPUI の既定は非 macOS で             「窓 0 枚 = ExitProcess(0)」なので、内部都合の 0 枚でも             **診断を 1 行も残さずプロセスが消える**（#872）"
        );
        assert!(
            text.contains("cx.on_window_closed("),
            "on_window_closed の診断が消えている。0 枚になった瞬間の記録が無いと             「静かに死んだ」の切り分けができない（#872）"
        );
        // 診断がアプリを落としてはいけない: close 観測子は `update_window` の内側から
        // 呼ばれるので、そこで entity を read すると lease 中に当たって panic する
        let obs = text
            .find("cx.on_window_closed(")
            .expect("on_window_closed の登録が見つからない");
        let body = &text[obs..];
        let body = &body[..body
            .find("\n        .detach();")
            .expect("観測子の終端が無い")];
        for forbidden in ["PrimaryApp", ".read(cx)", ".upgrade()", ".update("] {
            assert!(
                !body.contains(forbidden),
                "close 観測子が {forbidden} を使っている。update_window の内側から呼ばれるので \
                 entity に触ると gpui の double-lease で「診断がアプリを落とす」（#872）。\
                 枚数は observed_logical_windows() から引くこと"
            );
        }
        assert!(
            text.contains("window_lifecycle::last_window_close_here()"),
            "最後のウィンドウの扱いが window_lifecycle 経由でなくなっている。             方針を UI ツールキットの既定に戻すと #872 が再発する"
        );
    }

    /// 途中で死んだ run が「OK + 終了コード 0」にならないこと（#872 の番犬）。
    ///
    /// `on_app_quit` は最終項目の cmd-q 以外（ウィンドウ 0 枚の自動終了・最後のタブの
    /// close）からも通るので、OK マーカーを無条件に出すと**偽の緑**になる。
    /// 実際 Windows で `TAKO_APP_SELF_TEST_OK` + exit 0 が出るのを実測した
    #[test]
    fn 途中終了はokマーカーを出さない() {
        let text = source("src/main.rs");
        let ok_at = text
            .find("println!(\"TAKO_APP_SELF_TEST_OK\")")
            .expect("OK マーカーの印字が見つからない");
        // OK の直前に「最終項目まで到達したか」の判定があること
        let before = &text[..ok_at];
        let guard = before
            .rfind("SELF_TEST_AT_FINAL_STEP.load(")
            .expect("OK マーカーがラッチで守られていない（途中終了で偽の緑になる。#872）");
        assert!(
            before[guard..].contains("TAKO_APP_SELF_TEST_FAILED"),
            "ラッチが立っていないときに FAILED を出していない（#872）"
        );
        // ラッチを立てるのは最終項目（cmd-q を撃つ直前）だけ
        let sets: Vec<_> = text
            .match_indices("SELF_TEST_AT_FINAL_STEP.store(")
            .collect();
        assert_eq!(
            sets.len(),
            1,
            "ラッチを立てる箇所が 1 つではない（最終項目だけであること。#872）"
        );
        let after_set = &text[sets[0].0..];
        assert!(
            after_set[..400].contains("press(final_any, cx, \"cmd-q\")"),
            "ラッチが最終項目の cmd-q の直前に無い（#872）"
        );
    }

    #[test]
    fn ウィンドウclose診断は0枚を名指しする() {
        use crate::viewport_closed_log;
        use tako_core::platform::support::Platform;
        use tako_core::platform::window_lifecycle::{last_window_close, LastWindowClose};
        // 論理ウィンドウ数が取れないときも「?」で必ず 1 行出す
        let zero = viewport_closed_log(
            gpui::WindowId::default(),
            0,
            None,
            last_window_close(Platform::Windows),
        );
        assert!(zero.contains("残り gpui=0"), "0 枚が読み取れない: {zero}");
        assert!(zero.contains("#872"), "追跡番号が無い: {zero}");
        assert!(
            zero.contains(LastWindowClose::Quit.reason()),
            "方針の理由が入っていない: {zero}"
        );
        assert!(zero.contains("論理=?"), "論理不明が表せていない: {zero}");
        // 残っているときは方針を書かない（毎 close でノイズにしない）
        let some = viewport_closed_log(
            gpui::WindowId::default(),
            2,
            Some(3),
            last_window_close(Platform::MacOs),
        );
        assert!(some.contains("残り gpui=2"), "枚数が読めない: {some}");
        assert!(some.contains("論理=3"), "論理枚数が読めない: {some}");
        assert!(!some.contains("#872"), "0 枚でないのに警告している: {some}");
    }
}

/// セルフテストの待ち条件の番犬（#796）。
///
/// 「固定時間待って画面に文字が出ているはず」で書くと、負荷やビルド構成
/// （`visual-test` feature は gpui の leak-detection を有効にして数割遅くなる）で
/// **同じソースなのに落ちる項目が変わる**。実際に #601 / #600 / PDF アウトライン /
/// IME / tmux attach が main 由来の失敗として worker の完了判定を壊し続けた。
///
/// 正しい形は `wait_for_focused_text`（状態到達まで待ち、上限で偽 + 診断を出す）。
/// visual-test は CI で走らないので、**CI で毎回走る静的検査**としてここに置く。
#[cfg(test)]
mod selftest_wait_watchdog {
    /// 「固定待ちの直後に、画面の文字列が出ていることを前提にした check」を探す。
    ///
    /// 否定検査（`!focused_contains`）は対象外: 「出ないこと」の確認は
    /// 落ち着くまでの待ちが本質なので、固定待ちで良い
    /// （出るものを待つのに固定時間を使うのが誤り）
    fn fixed_wait_then_positive_contains(src: &str) -> Vec<usize> {
        let lines: Vec<&str> = src.lines().collect();
        let mut hits = Vec::new();
        for (index, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            if !(trimmed.starts_with("wait(cx, ") && trimmed.ends_with(").await;")) {
                continue;
            }
            let following = lines
                .iter()
                .skip(index + 1)
                .take(3)
                .map(|l| l.trim())
                .collect::<Vec<_>>()
                .join(" ");
            if !following.starts_with("check(") {
                continue;
            }
            // 肯定形が 1 つでもあれば違反（`!focused_contains` だけなら見逃す）
            let mut rest = following.as_str();
            while let Some(at) = rest.find("focused_contains(window") {
                if !rest[..at].ends_with('!') {
                    hits.push(index + 1);
                    break;
                }
                rest = &rest[at + 1..];
            }
        }
        hits
    }

    /// **打ち込んで描く疑似 TUI の fixture は、シェルの準備を待つ**（#903）。
    ///
    /// 使い方は 2 通りある。ペインの起動コマンドとして渡す（`shell_snippet_command`）か、
    /// 既にあるペインへ打ち込むか。後者は**シェルの起動途中だと打鍵が落ちる**ので、
    /// `wait_for_pane_ready` で準備を待ってから送らなければならない
    /// （Windows は pwsh + 器の二段の起動で 500ms では足りず、項目 100 が必ず落ちていた）。
    ///
    /// 検査は行番号の近傍（前後 100 行 = 1 項目ぶんの目安）にどちらかの形があるかで見る。
    /// パターンは `concat!` で分割して書く（番犬自身のソース行が検査対象に入るため）
    fn painted_fixture_without_ready_wait(src: &str) -> Vec<usize> {
        const WINDOW: usize = 100;
        let needle = concat!("paint_and", "_hold(");
        let as_command = concat!("shell_snippet", "_command");
        let ready = concat!("wait_for_pane", "_ready");
        let lines: Vec<&str> = src.lines().collect();
        let mut hits = Vec::new();
        for (index, line) in lines.iter().enumerate() {
            if !line.contains(needle) {
                continue;
            }
            let from = index.saturating_sub(WINDOW);
            let to = (index + WINDOW + 1).min(lines.len());
            let around = lines[from..to].join(" ");
            if around.contains(as_command) || around.contains(ready) {
                continue;
            }
            hits.push(index + 1);
        }
        hits
    }

    #[test]
    fn 打ち込む疑似画面のfixtureはシェルの準備を待っている() {
        let src = include_str!("main.rs");
        let hits = painted_fixture_without_ready_wait(src);
        assert!(
            hits.is_empty(),
            "main.rs:{hits:?} が「疑似 TUI を描くコマンドを、シェルの準備を待たずに\
             ペインへ打ち込む」形で書かれている。起動途中の PTY は打鍵を落とすので\
             `wait_for_pane_ready` で待つ（またはペインの起動コマンドとして渡す）こと（#903）"
        );
    }

    /// 検出力の担保: 番犬自身が空振りしないこと
    #[test]
    fn 番犬は準備待ちなしの打ち込みを見逃さず起動コマンド形は許す() {
        let bad = format!(
            "                let cmd = sh.{};\n                send(app, cmd);",
            concat!("paint_and", "_hold(body, 30)")
        );
        assert_eq!(painted_fixture_without_ready_wait(&bad), vec![1]);
        let waited = format!(
            "                let _ = {}.await;\n                let cmd = sh.{};",
            concat!("wait_for_pane", "_ready(window, cx, pane, timeout)"),
            concat!("paint_and", "_hold(body, 30)")
        );
        assert!(painted_fixture_without_ready_wait(&waited).is_empty());
        let as_command = format!(
            "                command: Some(sh.{}(\n                    &sh.{},\n                )),",
            concat!("shell_snippet", "_command"),
            concat!("paint_and", "_hold(body, 30)")
        );
        assert!(painted_fixture_without_ready_wait(&as_command).is_empty());
    }

    #[test]
    fn 画面の文字列を待つ検査は固定待ちに依存していない() {
        let src = include_str!("main.rs");
        let hits = fixed_wait_then_positive_contains(src);
        assert!(
            hits.is_empty(),
            "main.rs:{hits:?} が「固定待ち → 画面に文字が出ているはず」で書かれている。\
             負荷やビルド構成で落ちるフレークになるので `wait_for_focused_text`\
             （状態到達まで待つ）を使うこと（#796）"
        );
    }

    /// 検出力の担保: 番犬自身が空振りしないこと
    #[test]
    fn 番犬は固定待ちの肯定検査を見逃さず否定検査は許す() {
        let bad = "            wait(cx, 800).await;\n            \
                   check(focused_contains(window, cx, \"X\"), \"だめな形\");";
        assert_eq!(fixed_wait_then_positive_contains(bad), vec![1]);
        let negative = "            wait(cx, 800).await;\n            check(\n                \
                        !focused_contains(window, cx, \"X\"),\n                \"出ないことの確認\",";
        assert!(fixed_wait_then_positive_contains(negative).is_empty());
        let good = "            check(\n                \
                    wait_for_focused_text(window, cx, \"X\", Duration::from_secs(15)).await,\n";
        assert!(fixed_wait_then_positive_contains(good).is_empty());
    }
}

#[cfg(test)]
/// close 経路が「プレビュー状態の後始末」を勝手に列挙し直していないかの番犬（#821）。
///
/// GUI（`remove_pane_with`）と CLI / MCP（`detach_session`）が別々に
/// フィールドを並べていたため、後から足したものが片方だけに入り、
/// CLI / MCP で閉じたコードプレビューの行データがプロセス終了まで残っていた。
/// 一式は `drop_preview_pane_state` に集約してあり、ここはその形を保つ。
#[cfg(test)]
mod preview_cleanup_watchdog {
    /// `fn <name>` から次のトップレベル `    fn ` までを切り出す（同じ impl 内の関数本体）
    fn body_of<'a>(src: &'a str, name: &str) -> &'a str {
        let start = src
            .find(&format!("fn {name}("))
            .unwrap_or_else(|| panic!("{name} が見つからない"));
        let rest = &src[start..];
        let end = rest[1..]
            .find("\n    fn ")
            .map(|at| at + 1)
            .unwrap_or(rest.len());
        &rest[..end]
    }

    /// プレビュー由来のマップを直接 remove している行（後始末の独自列挙）。
    ///
    /// #826: 束縛名は経路ごとに違う（ペイン close は `&pane`、タブ close は
    /// ループ変数の `&id`）。`&pane` だけを見ていた最初の版は `remove_tab_with` の
    /// 独自列挙を見逃していたので、引数名に依存しない形にした
    fn direct_preview_removes(body: &str) -> Vec<String> {
        body.lines()
            .map(str::trim)
            .filter(|line| line.starts_with("self.preview") && line.contains(".remove(&"))
            .map(str::to_string)
            .collect()
    }

    /// #766 の番犬: 側路（`osc_sink`）の後始末も 3 つの close 経路すべてから呼ばれること。
    ///
    /// 残すとペイン ID が再利用されたとき（#210 の復元経路）**前のペインの最後の状態**を
    /// 新しいペインへ食わせてしまう。`prepare` 側でも残骸を消しているので二重の防御だが、
    /// close で消えないと「閉じたペインのファイルが data_dir に溜まる」ほうが残る
    #[test]
    fn close_経路は側路の後始末を集約関数に任せている() {
        let src = include_str!("main.rs");
        for name in ["remove_pane_with", "detach_session", "remove_tab_with"] {
            let body = body_of(src, name);
            assert!(
                body.contains("drop_pane_osc_sink("),
                "{name} が drop_pane_osc_sink を呼んでいない（#766）"
            );
        }
    }

    #[test]
    fn close_経路はプレビュー状態の後始末を集約関数に任せている() {
        let src = include_str!("main.rs");
        for name in ["remove_pane_with", "detach_session", "remove_tab_with"] {
            let body = body_of(src, name);
            assert!(
                body.contains("drop_preview_pane_state("),
                "{name} が drop_preview_pane_state を呼んでいない（#821）"
            );
            let strays = direct_preview_removes(body);
            assert!(
                strays.is_empty(),
                "{name} がプレビュー状態を独自に列挙している: {strays:?}。\
                 追加は drop_preview_pane_state（preview_render.rs）へ足すこと（#821）"
            );
        }
    }

    /// 検出力の担保: 番犬自身が空振りしないこと
    #[test]
    fn 番犬は独自列挙を見逃さない() {
        let bad = "    fn f(&mut self) {\n        self.preview_line_texts.remove(&pane);\n    }\n    fn g(";
        assert_eq!(
            direct_preview_removes(body_of(bad, "f")),
            vec!["self.preview_line_texts.remove(&pane);".to_string()]
        );
        let good =
            "    fn f(&mut self) {\n        self.drop_preview_pane_state(pane);\n    }\n    fn g(";
        assert!(direct_preview_removes(body_of(good, "f")).is_empty());
        // #826: ループ変数（タブ close は `&id`）でも見逃さない
        let bad_loop =
            "    fn f(&mut self) {\n        self.preview_body_lists.remove(&id);\n    }\n    fn g(";
        assert_eq!(
            direct_preview_removes(body_of(bad_loop, "f")),
            vec!["self.preview_body_lists.remove(&id);".to_string()]
        );
    }
}

/// GPUI ウィンドウ close の失敗を握り潰していないことの番犬（#828）。
///
/// `sync_viewports` は `drop_viewport` で対応表を先に落としてから close を投げるので、
/// ここを `let _ =` にすると失敗が**どこにも残らない**（#828 の調査では、この
/// 握り潰しが原因かどうかを判定するのに計装ビルドを 1 本起こす必要があった）。
#[cfg(test)]
mod viewport_close_diag {
    use super::viewport_close_failure_log;

    /// `fn <name>` から次のトップレベル `    fn ` までを切り出す
    fn body_of<'a>(src: &'a str, name: &str) -> &'a str {
        let start = src
            .find(&format!("fn {name}("))
            .unwrap_or_else(|| panic!("{name} が見つからない"));
        let rest = &src[start..];
        let end = rest[1..]
            .find("\n    fn ")
            .map(|at| at + 1)
            .unwrap_or(rest.len());
        &rest[..end]
    }

    /// close の戻り値を捨てている行
    fn swallowed_close(body: &str) -> Vec<String> {
        body.lines()
            .map(str::trim)
            .filter(|line| line.starts_with("let _ =") && line.contains("remove_window"))
            .map(str::to_string)
            .collect()
    }

    #[test]
    fn sync_viewports_は_close_失敗を記録する() {
        let src = include_str!("main.rs");
        let body = body_of(src, "sync_viewports");
        let strays = swallowed_close(body);
        assert!(
            strays.is_empty(),
            "sync_viewports が close の失敗を握り潰している: {strays:?}（#828）"
        );
        assert!(
            body.contains("viewport_close_failure_log("),
            "sync_viewports が close 失敗を persist.log へ残していない（#828）"
        );
    }

    /// 検出力の担保: 番犬自身が空振りしないこと
    #[test]
    fn 番犬は握り潰しを見逃さない() {
        let bad = "    fn f(&mut self) {\n        \
                   let _ = handle.update(cx, |_, window, _| window.remove_window());\n    }\n    fn g(";
        assert_eq!(swallowed_close(body_of(bad, "f")).len(), 1);
        let good = "    fn f(&mut self) {\n        \
                    if let Err(e) = handle.update(cx, |_, window, _| window.remove_window()) {}\n    }\n    fn g(";
        assert!(swallowed_close(body_of(good, "f")).is_empty());
    }

    #[test]
    fn 診断行は発生源と対象を含む() {
        let line = viewport_close_failure_log(
            "dispatch",
            tako_core::WindowId::from_raw(7),
            gpui::WindowId::default(),
            "window not found",
        );
        assert!(line.contains("logical=7"), "{line}");
        assert!(line.contains("window not found"), "{line}");
        assert!(line.contains("（発生源 dispatch）"), "{line}");
    }
}

/// セルフテストが注入した会話が定期更新に消されないことの番犬（#853）。
///
/// 項目 98（#725）は「MCP `tako_chat_copy` が UI と同じ結果を返す」を見るために、
/// 実 claude が動いていないペインへ fixture の会話を注入する。2 秒 tick の
/// `apply_chat_refresh` はそのペインを読んで**正しく**「チャットではない」と判断し
/// `chat_panes` から消すので、MCP を 3 回往復するあいだに必ず会話が消え、項目 98 が
/// 決定的に失敗して**以降の項目が一切走らなくなっていた**。
///
/// 直し方は「読み取り対象から fixture のペインを外す」（判定は変えない）。
/// visual-test と違って CI で毎回走る静的検査としてここに置く。
#[cfg(test)]
mod chat_fixture_pin_watchdog {
    /// 走査対象のソース。この番犬モジュール自身（検査したい文字列を含む）は除外する
    fn scanned(src: &'static str) -> &'static str {
        match src.find("mod chat_fixture_pin_watchdog") {
            Some(at) => &src[..at],
            None => src,
        }
    }

    /// `fn <name>` の**本体だけ**を切り出す（波括弧の対応で閉じる）。
    ///
    /// 「次の `    fn ` まで」で切ると、後続が `pub(crate) fn` ばかりの並びでは行が
    /// 一致せず関数を跨いで巨大な範囲を掴む（`pin_chat_fixture` まで含んでしまい、
    /// `collect_chat_targets` から除外を消しても番犬が素通りした = 実際に踏んだ）
    fn body_of<'a>(src: &'a str, name: &str) -> &'a str {
        let start = src
            .find(&format!("fn {name}("))
            .unwrap_or_else(|| panic!("{name} が見つからない（構造が変わったら番犬も見直す）"));
        let rest = &src[start..];
        let open = rest
            .find('{')
            .unwrap_or_else(|| panic!("{name} の本体が見つからない"));
        let mut depth = 0usize;
        for (at, ch) in rest[open..].char_indices() {
            match ch {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return &rest[..open + at + 1];
                    }
                }
                _ => {}
            }
        }
        panic!("{name} の本体が閉じていない")
    }

    #[test]
    fn 定期更新はfixtureのペインを読みに行かない() {
        let body = body_of(include_str!("chat_view.rs"), "collect_chat_targets");
        assert!(
            body.contains("chat_fixture_panes"),
            "collect_chat_targets が fixture ペインを除外していない。\
             セルフテストが注入した会話が 2 秒 tick に消され、項目 98（#725）が\
             決定的に失敗して以降の項目が走らなくなる（#853）"
        );
    }

    #[test]
    fn 項目98はmcpを叩く前にfixtureをpinしている() {
        let src = scanned(include_str!("main.rs"));
        let insert = src
            .find(r#""selftest-725".into()"#)
            .expect("項目 98 の fixture 注入が見つからない");
        let rest = &src[insert..];
        let pin = rest
            .find("pin_chat_fixture(chat_pane)")
            .expect("項目 98 が fixture を pin していない（#853）");
        let mcp = rest
            .find(r#""name":"tako_chat_copy""#)
            .expect("項目 98 の MCP 往復が見つからない");
        assert!(
            pin < mcp,
            "pin が MCP 往復より後にある（往復のあいだに 2 秒 tick が会話を消す。#853）"
        );
    }

    #[test]
    fn 項目98は定期更新を1周回して会話が残ることを見ている() {
        let src = scanned(include_str!("main.rs"));
        let insert = src
            .find(r#""selftest-725".into()"#)
            .expect("項目 98 の fixture 注入が見つからない");
        let rest = &src[insert..];
        let refresh = rest
            .find("collect_chat_targets()")
            .expect("項目 98 が定期更新の 1 周を回していない（#853）");
        let mcp = rest
            .find(r#""name":"tako_chat_copy""#)
            .expect("項目 98 の MCP 往復が見つからない");
        assert!(
            refresh < mcp,
            "定期更新の 1 周が MCP 往復より後にある。\
             tick が挟まるかを運に任せると修正前の詰まりが再現せず、\
             原因が特定できないまま残る（#853）"
        );
        assert!(
            rest[..mcp].contains("apply_chat_refresh"),
            "collect_chat_targets を呼ぶだけで反映していない = 消える経路を通っていない（#853）"
        );
    }

    #[test]
    fn mcpの判定はlistとcodeとmarkdownで別々に落ちる() {
        let src = scanned(include_str!("main.rs"));
        for needle in [
            "MCP tako_chat_copy の list が",
            "MCP tako_chat_copy の code が",
            "MCP tako_chat_copy の markdown が",
        ] {
            assert!(
                src.contains(needle),
                "{needle}… の判定が無い。1 個の `&&` 連鎖に戻すと\
                 どの経路で落ちたのか出力から確定できない（#853 / #796）"
            );
        }
    }

    /// 検出力の担保: 番犬自身が空振りしないこと
    #[test]
    fn 番犬はpinの欠落と順序違いを見つける() {
        // 後続は実ファイルと同じ `pub(crate) fn`。行一致で切る実装だと本体を跨いで
        // 掴んでしまい、除外を消しても素通りする（実際に踏んだので形で拘束する）
        let tail =
            "\n    }\n}\n\nimpl T {\n    pub(crate) fn pin_chat_fixture(&mut self) {\n        \
                    self.chat_fixture_panes.insert(p);\n    }\n}";
        let no_pin = format!("    fn collect_chat_targets(&self) -> Vec<T> {{\n        x(){tail}");
        assert!(!body_of(&no_pin, "collect_chat_targets").contains("chat_fixture_panes"));
        let pinned = format!(
            "    fn collect_chat_targets(&self) -> Vec<T> {{\n        \
             x().filter(|(p, _)| !self.chat_fixture_panes.contains(*p)){tail}"
        );
        assert!(body_of(&pinned, "collect_chat_targets").contains("chat_fixture_panes"));
        // 番犬モジュール自身は走査から外れている（自分の文字列で素通りしない）
        assert!(!scanned(include_str!("main.rs")).contains("mod chat_fixture_pin_watchdog"));
    }
}
